with feeders as (
    select
        md5(upper('LNK_PARTY_ROLE|' || (LNK_PARTY_ROLE_BK__POLICY_REF_NOMINEENAME))) as LNK_PARTY_ROLE_HK
        , NOMINEERELATION as RELATIONSHIP_TO_INSURED
        , NOMINEEDOB as NOMINEE_DATE_OF_BIRTH
        , APPOINTEENAME as APPOINTEE_NAME
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (LNK(HUB_PARTY = md5(normalise(upper(nullif(coalesce(nullif(trim(POLICY_REF),''),'') || '|NOMINEE|' || coalesce(nullif(trim(NOMINEENAME),''),''), '|NOMINEE|')))))) is not null
    union all
    select
        md5(upper('LNK_PARTY_ROLE|' || (LNK_PARTY_ROLE_BK__contract_id_nominee_name))) as LNK_PARTY_ROLE_HK
        , moninee_rel as RELATIONSHIP_TO_INSURED
        , cast(null as varchar) as NOMINEE_DATE_OF_BIRTH
        , cast(null as varchar) as APPOINTEE_NAME
        , 'BA_CCP_INSURED_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_insured_details') }}
    where (LNK(HUB_PARTY = md5(normalise(upper(nullif(coalesce(nullif(trim(contract_id),''),'') || '|NOMINEE|' || coalesce(nullif(trim(nominee_name),''),''), '|NOMINEE|')))))) is not null
),

resolved as (
    select
        LNK_PARTY_ROLE_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then RELATIONSHIP_TO_INSURED end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RELATIONSHIP_TO_INSURED end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then RELATIONSHIP_TO_INSURED end)) as RELATIONSHIP_TO_INSURED,
        max(case when SOURCE_RUN = 'opus_health_v2' then NOMINEE_DATE_OF_BIRTH end) as NOMINEE_DATE_OF_BIRTH,
        max(case when SOURCE_RUN = 'opus_health_v2' then APPOINTEE_NAME end) as APPOINTEE_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by LNK_PARTY_ROLE_HK
),

hashed as (
    select
        *,
        case when RELATIONSHIP_TO_INSURED is not null or NOMINEE_DATE_OF_BIRTH is not null or APPOINTEE_NAME is not null
                     then md5(upper(coalesce(cast(RELATIONSHIP_TO_INSURED as varchar), '') || '|' || coalesce(cast(NOMINEE_DATE_OF_BIRTH as varchar), '') || '|' || coalesce(cast(APPOINTEE_NAME as varchar), '')))
                end as SAT_LNK_ROLE_NOMINEE_BENEFICIARY_HASHDIFF
    from resolved
)

select * from hashed
where LNK_PARTY_ROLE_HK is not null
  and SAT_LNK_ROLE_NOMINEE_BENEFICIARY_HASHDIFF is not null
